<?php
require_once __DIR__ . '/includes/auth.php';requireLogin();$pdo=db();$uid=userId();$pageTitle='Transaksi Berulang';$activePage='recurring.php';$incomeCats=['Gaji','Freelance','Bisnis','Bonus','Komisi','Penjualan','Investasi','Hadiah','Pemasukan Lainnya'];$expenseCats=['Makanan','Minuman','Transportasi','Bensin','Parkir','Tagihan','Belanja','Hiburan','Gaming','Kesehatan','Pendidikan','Rumah Tangga','Pulsa/Internet','Fashion','Nongkrong','Travel','Pengeluaran Lainnya'];
if($_SERVER['REQUEST_METHOD']==='POST'){verifyCsrf();$action=$_POST['action']??'';if($action==='delete'){$st=$pdo->prepare('DELETE FROM recurring_transactions WHERE id=? AND user_id=?');$st->execute([(int)$_POST['id'],$uid]);flash('success','Transaksi berulang dihapus.');redirect('recurring.php');}if($action==='toggle'){$st=$pdo->prepare('UPDATE recurring_transactions SET active=NOT active WHERE id=? AND user_id=?');$st->execute([(int)$_POST['id'],$uid]);flash('success','Status transaksi berulang diperbarui.');redirect('recurring.php');}if($action==='save'){$id=(int)($_POST['id']??0);$type=$_POST['type']==='income'?'income':'expense';$amount=parseAmount($_POST['amount']??0);$category=trim((string)$_POST['category']);$desc=trim((string)$_POST['description']);$freq=(string)$_POST['frequency'];$next=(string)$_POST['next_date'];if($amount<=0||$category===''||!in_array($freq,['Harian','Mingguan','Bulanan','Tahunan'],true)||!validDate($next)){flash('error','Lengkapi nominal, kategori, frekuensi, dan tanggal berikutnya.');redirect('recurring.php?action='.($id?'edit&id='.$id:'add'));}if($id){$st=$pdo->prepare('UPDATE recurring_transactions SET type=?,amount=?,category=?,description=?,frequency=?,next_date=? WHERE id=? AND user_id=?');$st->execute([$type,$amount,$category,$desc,$freq,$next,$id,$uid]);}else{$st=$pdo->prepare('INSERT INTO recurring_transactions(user_id,type,amount,category,description,frequency,next_date) VALUES(?,?,?,?,?,?,?)');$st->execute([$uid,$type,$amount,$category,$desc,$freq,$next]);}flash('success','Transaksi berulang berhasil disimpan.');redirect('recurring.php');}}
$st=$pdo->prepare('SELECT * FROM recurring_transactions WHERE user_id=? ORDER BY active DESC,next_date');$st->execute([$uid]);$rows=$st->fetchAll();$edit=null;if(($_GET['action']??'')==='edit'){$st=$pdo->prepare('SELECT * FROM recurring_transactions WHERE id=? AND user_id=?');$st->execute([(int)$_GET['id'],$uid]);$edit=$st->fetch()?:null;}if(($_GET['action']??'')==='add')$edit=['id'=>0,'type'=>'expense','amount'=>'','category'=>'','description'=>'','frequency'=>'Bulanan','next_date'=>date('Y-m-d')];$user=currentUser($pdo);require __DIR__.'/includes/header.php';
?>
<div class="page-heading"><div><p class="eyebrow">Otomatis tetap teringat</p><h1>Transaksi Berulang</h1><p>Catat gaji, langganan, cicilan, dan tagihan rutin dengan tanggal berikutnya.</p></div><a class="btn btn-primary" href="?action=add"><i data-lucide="plus"></i> Tambah Berulang</a></div>
<section class="card"><div class="card-header"><div><h2 class="card-title">Daftar transaksi berulang</h2><p class="card-subtitle">Aktif/nonaktif dapat diubah kapan saja.</p></div></div><?php if(!$rows):?><div class="empty-state"><div class="empty-icon"><i data-lucide="refresh-cw"></i></div><strong>Belum ada transaksi berulang.</strong><p>Tambahkan transaksi rutin agar tidak lupa dicatat.</p><a class="btn btn-primary btn-sm" href="?action=add">Tambah Berulang</a></div><?php else:?><div class="table-wrap"><table class="data-table"><thead><tr><th>Jenis</th><th>Kategori</th><th>Nominal</th><th>Frekuensi</th><th>Tanggal berikutnya</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($rows as $row):?><tr><td><span class="badge <?=$row['type']==='income'?'success':'danger'?>"><?=$row['type']==='income'?'Pemasukan':'Pengeluaran'?></span></td><td><strong><?=e($row['category'])?></strong><br><small class="form-hint"><?=e($row['description']?:'')?></small></td><td class="amount <?=$row['type']==='income'?'positive':'negative'?>"><?=formatRupiah($row['amount'])?></td><td><?=e($row['frequency'])?></td><td><?=e(date('d/m/Y',strtotime($row['next_date'])))?></td><td><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrfToken())?>"><input type="hidden" name="action" value="toggle"><input type="hidden" name="id" value="<?=(int)$row['id']?>"><button class="badge <?=$row['active']?'success':'neutral'?>" type="submit"><?=$row['active']?'Aktif':'Nonaktif'?></button></form></td><td><div class="actions"><a class="btn btn-ghost btn-sm icon-btn" href="?action=edit&id=<?=(int)$row['id']?>"><i data-lucide="pencil"></i></a><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrfToken())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=(int)$row['id']?>"><button class="btn btn-ghost btn-sm icon-btn" data-confirm="Hapus transaksi berulang ini?" type="submit"><i data-lucide="trash-2"></i></button></form></div></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section>
<div class="modal <?=$edit?'is-open':''?>" id="recurring-modal"><div class="modal-head"><div><h3><?=$edit&&$edit['id']?'Edit':'Tambah'?> Transaksi Berulang</h3><p>Atur pola dan tanggal berikutnya.</p></div><button class="icon-button" data-close-modal type="button"><i data-lucide="x"></i></button></div><form method="post" data-amount-form><input type="hidden" name="csrf_token" value="<?=e(csrfToken())?>"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=(int)($edit['id']??0)?>"><div class="form-grid"><div class="form-field"><label>Jenis</label><select class="select" name="type"><option value="income" <?=($edit['type']??'')==='income'?'selected':''?>>Pemasukan</option><option value="expense" <?=($edit['type']??'')==='expense'?'selected':''?>>Pengeluaran</option></select></div><div class="form-field"><label>Nominal</label><input class="input" name="amount" data-amount value="<?=e($edit['amount']??'')?>" required></div><div class="form-field"><label>Kategori</label><input class="input" name="category" value="<?=e($edit['category']??'')?>" required></div><div class="form-field"><label>Frekuensi</label><select class="select" name="frequency"><?php foreach(['Harian','Mingguan','Bulanan','Tahunan'] as $freq):?><option <?=$freq===($edit['frequency']??'Bulanan')?'selected':''?>><?=$freq?></option><?php endforeach;?></select></div><div class="form-field"><label>Tanggal berikutnya</label><input class="input" type="date" name="next_date" value="<?=e($edit['next_date']??'')?>" required></div><div class="form-field"><label>Deskripsi</label><input class="input" name="description" value="<?=e($edit['description']??'')?>"></div></div><div class="modal-actions"><button class="btn btn-ghost" data-close-modal type="button">Batal</button><button class="btn btn-primary" type="submit">Simpan</button></div></form></div>
